const allQ=()=>S.docs.flatMap(d=>d.q);
const emptyBox=(ic,t,s)=>`<div class=empty><div class=ic>${I(ic)}</div><h3>${t}</h3><div class="mono mut" style="margin-top:6px">${s}</div></div>`;
function libDeckTop(v){return`<div class=top><button onclick="A('menu','dots')">${I('ellipsis-vertical')}</button><div class=sp></div>${v=='lib'?`<button onclick="A('menu','plus')">${I('plus')}${I('chevron-down')}</button>`:`<button onclick="A('modal','deck')">${I('plus')}</button>`}<div class=sp></div>${v=='lib'?`<button class="${S.sq||S.find?'on':''}" onclick="S.sq=!S.sq;if(!S.sq)S.find='';render()">${I('search')}</button>`:'<span style="width:44px"></span>'}</div>${v=='lib'&&(S.sq||S.find)?`<div style="padding:0 14px"><input id=qs value="${esc(S.find)}" placeholder="Cerca per titolo" oninput="S.find=this.value;$('#libgrid').innerHTML=libCards()"></div>`:''}`}
const libDocs=()=>{const D=S.docs.filter(d=>d.title.toLowerCase().includes(S.find.toLowerCase()));return S.ord=='tit'?[...D].sort((a,b)=>a.title.localeCompare(b.title)):[...D].reverse()};
function libCards(){const last=Math.max(...S.docs.map(d=>d.id));return libDocs().map(d=>{const pr=d.prog||0,au=(d.authors||[]).slice(0,2).join(', ')+(d.year?' · '+d.year:''),dt=d.id>1e12?'Aggiunta il '+new Date(d.id).toLocaleDateString('it-IT'):'';
 return`<article class=src onclick="A('open',${d.id})"><div class=cover>${d.kind=='pdf'?`<img data-t=${d.id}>`:''}<div class=exc>${esc((d.paras[0]||'').slice(0,190))}</div></div><div class=sbd><div class=tags>${d.id==last?'<span class="tag hi">Ultima aggiunta</span>':''}<span class=tag>${d.kind=='pdf'?'PDF':'Testo'}</span><span class=acts><button onclick="event.stopPropagation();A('rndoc',${d.id})">${I('pencil')}</button><button onclick="event.stopPropagation();A('rmdoc',${d.id})">${I('trash-2')}</button></span></div><h3>${esc(d.title)}</h3><div class="mono mut">${esc(au||dt)}</div><div class=prog><i style="width:${pr}%"></i></div><div class="mono mut">${pr}% letto${d.pages?' · '+d.pages+' pag.':''}</div><div class=cnt><span>${I('key-round')}${d.kw.length}</span><span>${I('circle-help')}${d.q.length}</span><span>${I('sticky-note')}${d.n.length}</span><span>${I('network')}${(d.maps||[]).length}</span></div></div></article>`}).join('')}
const libView=()=>`<main><div class=sec><span class=mono>Libreria</span><span class="mono mut">${S.docs.length} ${S.docs.length==1?'fonte':'fonti'}</span></div>${S.docs.length?`<div id=libgrid class="srcs ${S.lay=='list'?'one':''}">${libCards()}</div>`:emptyBox('library-big','La libreria è vuota','Carica una fonte con il pulsante in alto')}</main>`;
function deckCard(k){const C=cards(k),n=C.length,dd=due(k).length,bx=[1,2,3,4,5].map(b=>C.filter(q=>q.box==b).length),mx=Math.max(...bx,1);
 return`<article class="dk ${dd?'due':'ok'}"><div class=dkp><div class=dkn>${n}</div><div class="mono mut">${n?(n==1?'carta':'carte'):'mazzo senza domande'}</div>${n?`<div class=hist>${bx.map(c=>`<div><i style="height:${Math.max(c/mx*100,6)}%" class="${c?'f':''}"></i><span>${c}</span></div>`).join('')}</div><div class=hl2>${[1,2,3,4,5].map(b=>`<span>S${b}</span>`).join('')}</div>`:''}</div><div class=dkb onclick="A('menu','dk${k.id}')"><span class=st>${dd?`${I('layers')}${dd} da ripassare`:`${I('check')}In pari`}</span><h3>${esc(k.name)}</h3><div class="mono mut">${k.src.length?k.src.length+(k.src.length>1?' fonti':' fonte'):'nessuna fonte'}</div></div><button class=dkm onclick="A('menu','dk${k.id}')">${I('ellipsis-vertical')}</button></article>`}
function deckView(){if(S.rev)return`<main>${reviewView()}</main>`;const Q=allQ(),du=Q.filter(q=>q.due<=today()),nx=Q.filter(q=>q.due>today()).map(q=>q.due-today()).sort((a,b)=>a-b)[0];
 return`<main><section class=hero><div><span class="tag hi">Oggi</span><h2>${du.length?du.length+(du.length==1?' flashcard da ripassare':' flashcard da ripassare'):'Nessuna flashcard da ripassare'}</h2><p class="mono mut">${du.length?'Ripassa ora per consolidare':nx?'Prossima scadenza '+(nx==1?'domani':'tra '+nx+' giorni'):'Torna quando una flashcard sarà in scadenza'}</p>${du.length?`<button class=pri onclick="A('studyall')">Inizia il ripasso</button>`:''}</div><div class=stack><i></i><i></i><i></i></div></section>
 <div class=sec><span class=mono>Mazzi</span><span class="mono mut">${S.decks.length}</span></div>${S.decks.length?`<div class=dks>${S.decks.map(deckCard).join('')}</div>`:emptyBox('layers','Non hai creato mazzi','Crea un mazzo con il pulsante in alto')}</main>`}
function reviewView(){const r=S.rev;if(r.end)return`<section class=done><span class="tag hi">Completato</span><h2>Ripasso concluso</h2><p class="mono mut">${r.q.length} carte${r.m=='test'?' · nulla è stato salvato':''}</p><button class=pri onclick="A('view','deck')">Torna ai mazzi</button></section>`;
 const c=allQ().find(q=>q.id==r.q[r.k]),nm=r.id&&dk(r.id)?esc(dk(r.id).name):'Tutte le scadenze';
 return`<div class=rvh><button onclick="A('view','deck')">${I('x')}</button><div><div class=mono>${nm}</div><div class=prog style="margin-top:6px"><i style="width:${r.k/r.q.length*100}%"></i></div></div><span class="mono mut">${r.k+1}/${r.q.length}</span></div><div class=bxr>${[1,2,3,4,5].map(b=>`<span class="${b==c.box?'on':''}">S${b}</span>`).join('')}</div><section class=fc><div class="mono mut">Domanda</div><div class=fq>${esc(c.q)}</div>${r.show?`<hr><div class="mono mut">Risposta</div><div class=fa>${esc(c.a)}</div>`:''}</section><div class=fbtn>${r.show?`<button class=bad onclick="A('ans',false)">Da rivedere</button><button class=pri onclick="A('ans',true)">Ricordata</button>`:`<button class=pri onclick="A('show')">Mostra risposta</button>`}</div>`}
const tabbar=v=>`<nav class=tabbar><button class="${v=='lib'?'on':''}" onclick="A('view','lib')">${I('library-big')}<span>Libreria</span></button><button class="${v=='deck'?'on':''}" onclick="A('view','deck')">${I('layers')}<span>Flashcard</span></button></nav>`;
function fillCovers(){document.querySelectorAll('img[data-t]').forEach(im=>idbGet('t'+im.dataset.t).then(u=>u?im.src=u:im.remove()))}
/* ---- cerca nel testo, backup, esporta appunti, vai a ---- */
function modalMisc(){if(S.modal=='find')return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Cerca nel testo</h2><input id=fq placeholder="Scrivi una parola o una frase" oninput="findRun(this.value)"><div id=fres style="max-height:50vh;overflow:auto"></div></div>`;
 if(S.modal=='edoc'){const o=S.docs.find(o=>o.id==S.edoc);if(!o)return'';return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Modifica i dettagli</h2><div class=lab>Titolo</div><input id=ft value="${esc(o.title)}"><div class=lab>Anno</div><input id=fy value="${esc(o.year||'')}" placeholder="es. 2019"><div class=lab>Autori (separati da virgola)</div><input id=fa value="${esc((o.authors||[]).join(', '))}">${o.kind=='pdf'?`<button style="width:100%;margin-bottom:12px" onclick="reanalyze(${o.id})">Rianalizza il PDF (frasi, indice, autori)</button>`:''}<div style="display:flex;gap:8px;justify-content:flex-end"><button onclick="A('close')">Annulla</button><button class=pri onclick="A('saveedoc')">${I('check')}Salva</button></div></div>`}
 if(S.modal=='bk')return`<div class=ov onclick="A('close')"></div><div class=modal><h2>Backup</h2><p class=mut>Salva note, domande, mappe e mazzi in un file. I PDF originali non sono inclusi: restano sul dispositivo.</p><button class=pri onclick="backupExp()">${I('download')}Esporta backup</button><label class=card style="display:block;text-align:center;cursor:pointer;margin:14px 0">Importa un backup<input type=file hidden accept=".json" onchange="backupImp(this.files[0])"></label><button onclick="A('close')">Chiudi</button></div>`;return''}
function findRun(q){q=q.trim().toLowerCase();const L=sents(doc()),o=[];if(q.length>1)L.forEach((s,i)=>{const t=s.t,k=t.toLowerCase().indexOf(q);if(k>=0&&o.length<40)o.push(`<div class=item style="cursor:pointer" onclick="findGo(${i})">${esc(t.slice(Math.max(0,k-40),k))}<mark>${esc(t.slice(k,k+q.length))}</mark>${esc(t.slice(k+q.length,k+q.length+70))}${s.pg!=null?` <span class="mono mut">p.${s.pg+1}</span>`:''}</div>`)});$('#fres').innerHTML=o.join('')||(q.length>1?'<div class=mut>Nessun risultato.</div>':'')}
const findGo=i=>{S.modal=null;jumpTo(i)};
function kwGo(i){const d=doc(),L=sents(d),k=d.kw[i].toLowerCase(),f=(a)=>L.findIndex((s,x)=>x>=a&&s.t.toLowerCase().includes(k));let j=f(S.i+1);if(j<0)j=f(0);if(j>=0)jumpTo(j)}
function backupExp(){dl(new Blob([JSON.stringify({v:1,docs:S.docs,decks:S.decks})],{type:'application/json'}),'studio-backup.json')}
async function backupImp(f){if(!f)return;try{const j=JSON.parse(await f.text());let n=0;(j.docs||[]).forEach(d=>{if(!S.docs.some(o=>o.id==d.id)){S.docs.push(d);n++}});(j.decks||[]).forEach(k=>{if(!S.decks.some(o=>o.id==k.id))S.decks.push(k)});S.modal=null;save();render();tell(n+' documenti importati')}catch(e){tell('File non valido')}}
function exportMd(){const d=doc(),h=[`# ${d.title}`,''];if(d.kw.length)h.push('## Parole chiave',d.kw.map(k=>'- '+k).join('\n'),'');if(d.s.length)h.push('## Riassunti',...d.s.map(x=>x.x+'\n'));if(d.n.length)h.push('## Note',...d.n.map(x=>x.x+'\n'));if(d.q.length)h.push('## Domande',...d.q.map(q=>`**${q.q}**\n${q.a}\n`));S.menu=null;render();dl(new Blob([h.join('\n')],{type:'text/markdown'}),(d.title.replace(/[^\w\- ]+/g,'').trim()||'appunti')+'.md')}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key=='f'&&S.view=='read'){e.preventDefault();A('modal','find')}});

/* ---- v0.2: dialoghi interni, layout mobile, indice automatico ---- */
const MOB=()=>innerWidth<700;let LASTM=MOB(),RT=0;addEventListener('resize',()=>{clearTimeout(RT);RT=setTimeout(()=>{if(MOB()!==LASTM){LASTM=MOB();render()}},150)});
let DLGR=null;
function form(title,fields,ok){return new Promise(r=>{DLGR=r;S.dlg={title,fields,ok:ok||'Salva',kind:'form'};render();setTimeout(()=>document.getElementById('f0')?.focus(),60)})}
const sure=(msg,ok)=>new Promise(r=>{DLGR=r;S.dlg={title:msg,kind:'sure',ok:ok||'Elimina'};render()});
const tell=msg=>new Promise(r=>{DLGR=r;S.dlg={title:msg,kind:'tell',ok:'OK'};render()});
function dlgEnd(ok){const g=S.dlg;if(!g)return;const v=ok?(g.kind=='form'?g.fields.map((f,i)=>document.getElementById('f'+i).value):true):null;S.dlg=null;render();const r=DLGR;DLGR=null;r&&r(v)}
function dlgHTML(){const g=S.dlg;if(!g)return'';return`<div class=ov style="z-index:40" onclick="dlgEnd(false)"></div><div class=modal style="z-index:41"><h2 style="font-size:${g.kind=='form'?'1.4rem':'1.2rem'}">${esc(g.title)}</h2>${g.kind=='form'?g.fields.map((f,i)=>`<div class=lab>${esc(f.l)}</div>${f.rows?`<textarea id=f${i} rows=${f.rows}>${esc(f.v||'')}</textarea>`:`<input id=f${i} value="${esc(f.v||'')}">`}`).join(''):''}<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:8px">${g.kind=='tell'?'':`<button onclick="dlgEnd(false)">Annulla</button>`}<button class=pri onclick="dlgEnd(true)">${g.ok}</button></div></div>`}
function dotsMenu(){const set=`<div class=h>IMPOSTAZIONI</div>${tip(I('sparkles')+' Assistente AI (chiave Gemini)',"A('modal','key')")}${tip(I('download')+' Backup…',"A('modal','bk')")}`;
 if(S.view=='read'){const pdf=doc().kind=='pdf';return mn('top:56px;left:8px',`<div class=h>LETTORE</div>${tip(I('search')+' Cerca nel testo',"A('modal','find')")}${tip(I('panel-left')+' Indice',"A('side','idx')")}${pdf?tip(I('layers')+' Anteprime pagine',"A('side','th')"):''}${pdf?tip(I('align-left')+(S.pdfText?' Mostra le pagine':' Mostra il testo estratto'),"A('pt')"):''}${tip(I('file-text')+' Esporta appunti (.md)',"exportMd()")}${set}`)}
 return mn('top:56px;left:8px',`<div class=h>DISPOSIZIONE</div>${tip((S.lay=='grid'?'✓ ':'')+'Griglia',"A('lay','grid')")}${tip((S.lay=='list'?'✓ ':'')+'Lista',"A('lay','list')")}<div class=h>ORDINA PER</div>${tip((S.ord=='ins'?'✓ ':'')+'Inserimento',"A('ord','ins')")}${tip((S.ord=='tit'?'✓ ':'')+'Titolo',"A('ord','tit')")}${set}`)}
function readTop(){const M=MOB(),vm=M&&S.vm==1?0:S.vm;
 const seg=`<div class=seg>${(M?[0,2]:[0,1,2]).map(k=>`<button class="${vm==k?'on':''}" onclick="A('vm',${k})">${[I('file-text'),I('columns-2'),I('network')][k]}</button>`).join('')}</div>`;
 const foc=`<div class=seg><button class="${S.focus?'on':''}" onclick="A('focus')">${I('scan-text')}${M?'':'<span class=lb>Focus</span>'}</button><button onclick="A('menu','gran')">${I('chevron-down')}</button></div>`;
 if(M)return`<div class="top m"><button onclick="A('view','lib')">${I('house')}</button>${foc}${seg}<button onclick="A('menu','plus')">${I('plus')}</button><button onclick="A('menu','dots')">${I('ellipsis-vertical')}</button></div>`;
 return`<div class=top><button onclick="A('view','lib')">${I('house')}</button><button onclick="A('menu','dots')">${I('ellipsis-vertical')}</button><button class="${S.side?'on':''}" onclick="A('menu','side')">${I('panel-left')}${I('chevron-down')}</button><div class=sp></div>${foc}${seg}<button onclick="A('menu','plus')">${I('plus')}</button>${pdfToggle()}<button title="Cerca nel testo (Ctrl+F)" onclick="A('modal','find')">${I('search')}</button><div class=sp></div></div>`}
function readNav(d){const a=S.focus?`<button onclick="A('go',-1)">${I('chevron-left')}</button><button onclick="A('go',1)">${I('chevron-right')}</button>`:'';if(MOB())return a?`<div class="nav fl">${a}</div>`:'';const z=pdfZoomBtns(d);return a||z?`<div class=nav>${a}${z}</div>`:''}
const idxCmp=(a,b)=>(a.pg??0)-(b.pg??0)||(a.s??a.i??0)-(b.s??b.i??0);
const idxIndex=(L,x)=>x.pg!=null?Math.max(0,L.findIndex(z=>z.pg==x.pg&&z.e>x.s)):Math.min(x.i||0,L.length-1);
function jumpIdx(id){const d=doc(),x=(d.idx||[]).find(o=>o.id==id);if(x)jumpTo(idxIndex(sents(d),x))}
async function idxAdd(l){const d=doc(),L=sents(d),c=L[Math.min(S.i,L.length-1)],r=await form("Nuova sezione dell'indice",[{l:'Titolo',v:c.t.trim().slice(0,60)}]);if(r&&r[0].trim()){(d.idx=d.idx||[]).push({id:Date.now(),lv:l,t:r[0].trim(),i:S.i,pg:c.pg,s:c.s});d.idx.sort(idxCmp);S.side='idx';S.menu=null;save();render()}}
function sideHTML(d){if(!S.side||!d)return'';const pdf=d.kind=='pdf'&&!S.pdfText;
 if(S.side=='th'&&pdf)return`<div class=sidebar><div class=lab>Anteprime</div>${Array.from({length:d.pages},(_,n)=>`<div class=th onclick="jumpPage(${n})"><img data-th=${n}><div class=mut>${n+1}</div></div>`).join('')}</div>`;
 const L=sents(d),ix=(d.idx||[]),pos=ix.map(x=>idxIndex(L,x));let act=-1;pos.forEach((p,k)=>{if(p<=S.i)act=k});
 return`<div class=sidebar><div class=lab>Indice</div>${ix.map((x,k)=>`<div class="ix l${x.lv}${k==act?' on':''}" onclick="jumpIdx(${x.id})">${esc(x.t)}${acts('idx',x.id,1)}</div>`).join('')||'<div class=mut style="margin-top:8px">Nessuna sezione. Creane una dal menu ＋ → Sezione indice.</div>'}</div>`}
